declare(strict_types=1);require_once __DIR__.'/bootstrap.php';
use Flexgrid\Modules\AdminBanking\Application\UseCase\AcceptBankMatch;use Flexgrid\Modules\AdminBanking\Application\UseCase\IgnoreBankTransaction;use Flexgrid\Modules\AdminBanking\Contract\BankMatchProcessorInterface;use Flexgrid\Modules\AdminBanking\Contract\BankMatchProposalRepositoryInterface;use Flexgrid\Modules\AdminBanking\Contract\BankTransactionRepositoryInterface;use Flexgrid\Modules\AdminBanking\Domain\Model\BankMatchProposal;use Flexgrid\Modules\AdminBanking\Domain\Model\BankTransaction;use Flexgrid\Modules\AdminBanking\Domain\ValueObject\BankDate;use Flexgrid\Modules\AdminBanking\Domain\ValueObject\BankSourceSnapshot;use Flexgrid\Modules\AdminBanking\Domain\ValueObject\CounterpartySnapshot;use Flexgrid\Modules\AdminCore\Context\TenantContext;use Flexgrid\Modules\AdminCore\Contract\TransactionManagerInterface;use Flexgrid\Modules\AdminCore\ValueObject\Currency;use Flexgrid\Modules\AdminCore\ValueObject\Money;use Flexgrid\Modules\AdminCore\ValueObject\TenantId;use Flexgrid\Utils\_Time;
final class DecisionTransactions implements BankTransactionRepositoryInterface{public$item,$updates=0;public function insert(BankTransaction$t,int$c):void{$this->item=$t;}public function findByExternalId(TenantId$t,string$a,string$e):?BankTransaction{return null;}public function findByPublicId(TenantId$t,string$p):?BankTransaction{return$this->item!==null&&$this->item->getTenantId()->equals($t)&&$this->item->getPublicId()===$p?$this->item:null;}public function findByPublicIdForUpdate(TenantId$t,string$p):?BankTransaction{return$this->findByPublicId($t,$p);}public function updateMatchState(BankTransaction$t,int$updatedAt):void{$this->item=$t;++$this->updates;}}final class DecisionProposals implements BankMatchProposalRepositoryInterface{public$items=[];public function findByTransaction(TenantId$t,string$id):array{return$this->items;}public function replaceForTransaction(TenantId$t,string$id,array$items):void{$this->items=$items;}}final class DecisionProcessor implements BankMatchProcessorInterface{public$calls=0;public function supports(string$type):bool{return$type==='invoice';}public function process(TenantId$t,BankTransaction$transaction,string$target):void{++$this->calls;if($target!=='invoice-1'){throw new DomainException('Onjuist doel.');}}}final class DecisionTxManager implements TransactionManagerInterface{public function transactional(callable$operation){return$operation();}}
function decisionTransaction(string$id,TenantId$tenant):BankTransaction{return new BankTransaction($id,$tenant,'account-1','import-1','external-'.$id,new BankDate('2026-09-20'),new Money(12100,Currency::euro()),new CounterpartySnapshot('Klant'),'Factuurbetaling','F-1',new BankSourceSnapshot('abn_tab',str_repeat('b',64),[]));}
$tenant=new TenantId('decision-test');$repository=new DecisionTransactions();$repository->item=decisionTransaction('tx-1',$tenant);$proposals=new DecisionProposals();$proposals->items=[new BankMatchProposal('proposal-1',$tenant,'tx-1','invoice','invoice-1',9500,'Exacte match.',1770000000)];$processor=new DecisionProcessor();$accept=new AcceptBankMatch(new TenantContext($tenant),new DecisionTxManager(),$repository,$proposals,[$processor],new _Time(1770000100));$matched=$accept->execute('tx-1','proposal-1');adminBankingAssert($matched->getStatus()->getValue()==='matched'&&$matched->getMatchedTargetPublicId()==='invoice-1','Bevestigen moet bankregel aan het voorgestelde doel koppelen.');$accept->execute('tx-1','proposal-1');adminBankingAssert($processor->calls===1&&$repository->updates===1,'Dezelfde bevestiging moet idempotent zijn.');$ignoreRepository=new DecisionTransactions();$ignoreRepository->item=decisionTransaction('tx-2',$tenant);$ignore=new IgnoreBankTransaction(new TenantContext($tenant),new DecisionTxManager(),$ignoreRepository,new _Time(1770000200));$ignored=$ignore->execute('tx-2');$ignore->execute('tx-2');adminBankingAssert($ignored->getStatus()->getValue()==='ignored'&&$ignoreRepository->updates===1,'Negeren moet idempotent alleen de bankstatus aanpassen.');adminBankingAssertThrows(DomainException::class,function()use($accept){$accept->execute('tx-1','missing');},'Een onbekend voorstel moet worden geweigerd.');echo "AdminBanking match decision tests passed.\n";
